import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load font at module level to guarantee availability before frame 0
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type SilhouetteTransferProps = Record<string, any>;

const Silhouette: React.FC<{
  fillLevel: number;
  color: string;
  emptyOpacity: number;
  id: string;
  imageUrl: string;
}> = ({ fillLevel, color, emptyOpacity, id, imageUrl }) => {
  const filterId = `tint-${id}`;

  return (
    <div style={{ width: "100%", height: "100%", position: "relative", transition: "none" }}>
      {/* SVG filter strictly for colorizing the alpha mask of the PNG image */}
      <svg width="0" height="0" style={{ position: "absolute", pointerEvents: "none" }}>
        <filter id={filterId} colorInterpolationFilters="sRGB">
          <feFlood floodColor={color} result="flood" />
          <feComposite in="flood" in2="SourceAlpha" operator="in" />
        </filter>
      </svg>
      
      {/* Background shape (empty state) */}
      <Img 
        src={imageUrl} 
        style={{ 
          width: "100%", 
          height: "100%", 
          objectFit: "contain",
          position: "absolute",
          inset: 0,
          opacity: emptyOpacity,
          filter: `url(#${filterId}) drop-shadow(0px 8px 16px ${color}40)`,
          transition: "none"
        }} 
      />
      
      {/* Foreground shape (filled state), clipped strictly using inset based on fill percentage */}
      <Img 
        src={imageUrl} 
        style={{ 
          width: "100%", 
          height: "100%", 
          objectFit: "contain",
          position: "absolute",
          inset: 0,
          filter: `url(#${filterId})`,
          clipPath: `inset(${100 - (fillLevel * 100)}% 0 0 0)`,
          transition: "none"
        }} 
      />
    </div>
  );
};

const Counter: React.FC<{ value: number }> = ({ value }) => {
  const percentage = Math.round(value * 100);
  
  return (
    <div style={{
      position: 'absolute',
      top: '50%',
      left: '50%',
      transform: 'translate(-50%, -50%)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      pointerEvents: 'none',
      transition: "none"
    }}>
      <div style={{
        backgroundColor: 'rgba(20, 20, 20, 0.9)',
        padding: '16px 32px',
        borderRadius: '40px',
        border: '2px solid rgba(255, 255, 255, 0.1)',
        boxShadow: '0 12px 40px rgba(0, 0, 0, 0.5)',
        minWidth: '180px',
        textAlign: 'center',
        transition: "none"
      }}>
        <span style={{
          fontFamily: spaceGroteskFamily,
          fontSize: '56px',
          fontWeight: 700,
          color: '#ffffff',
          fontVariantNumeric: 'tabular-nums',
          letterSpacing: '-0.02em',
          transition: "none"
        }}>
          {percentage}%
        </span>
      </div>
    </div>
  );
};

const SilhouetteTransfer: React.FC<SilhouetteTransferProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  leftColor = "#FFD700",
  rightColor = "#FFFFFF",
  emptyOpacity = 0.15,
  silhouetteImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/4813ae4e599c4f1ebcca29a9e9fcba2c.png",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely parse transparent logic before rendering
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate robust animation timing independent of variable duration input
  const totalFrames = durationInSeconds * fps;
  const startFrame = Math.min(fps, totalFrames * 0.2); // wait 1 sec or 20% max
  const endFrame = Math.max(startFrame + 1, totalFrames - fps); // finish 1 sec prior

  // Ensure strict monotonicity for interpolation
  const progress = interpolate(
    frame,
    [startFrame, endFrame],
    [0, 1],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Derive isolated values to maintain pure functional architecture
  const leftFill = 1 - progress;
  const rightFill = progress;

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      display: 'flex', 
      flexDirection: 'row', 
      justifyContent: 'center', 
      alignItems: 'center', 
      gap: width * 0.1,
      transition: "none"
    }}>
      {/* Left Silhouette (Source) */}
      <div style={{ position: 'relative', width: width * 0.25, height: height * 0.75, transition: "none" }}>
         <Silhouette fillLevel={leftFill} color={leftColor} emptyOpacity={emptyOpacity} id="left" imageUrl={silhouetteImage} />
         <Counter value={leftFill} />
      </div>
      
      {/* Right Silhouette (Destination) */}
      <div style={{ position: 'relative', width: width * 0.25, height: height * 0.75, transition: "none" }}>
         <Silhouette fillLevel={rightFill} color={rightColor} emptyOpacity={emptyOpacity} id="right" imageUrl={silhouetteImage} />
         <Counter value={rightFill} />
      </div>
    </AbsoluteFill>
  );
};

export default SilhouetteTransfer;